58	 */
59	static int _ResetFiberDdmStatus(const uint8_t aPortNo)
60	{
61	    struct FiberCheckPortStatus tmpStatus;
62	    struct FiberCheckStatus*  fiber_check_status_shm_ptr = NULL;
63	    int ret = FIBER_CHECK_ERR_DEFAULT;
64	
65	    memset(&tmpStatus, 0, sizeof(struct FiberCheckPortStatus));
66	
67	     // Wait semaphore
68	    LibUtil_SemWait(kSemCritSecSrvTypeFiberCheckStatusSrv);
69	
70	    // Open share memory
